window.QUESTION_TOPICS = window.QUESTION_TOPICS || {};
window.QUESTION_TOPICS["content/08_architecture_and_design/01_basic.md"] = [{"id":"content/08_architecture_and_design/01_basic.md:3e7487e6d9ab2b7f:1","question":"<p>(L1 [T]) Что такое CAP theorem?</p>\n","answer":"<p><strong>Ответ:</strong> При сетевом разделении нельзя одновременно гарантировать linearizability и ответ каждому запросу к неотказавшему узлу. Выбор C/A относится к поведению во время partition, а не к произвольным «двум из трёх».</p>\n<p><strong>Типичная ошибка:</strong> Считать partition tolerance выключаемой опцией реальной распределённой сети.</p>\n<p><strong>Источник:</strong> <a href=\"https://groups.csail.mit.edu/tds/papers/Gilbert/Brewer2.pdf\">Gilbert, Lynch: Perspectives on CAP</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":19},{"id":"content/08_architecture_and_design/01_basic.md:9c7d9e7ff7e2d71f:1","question":"<p>(L1 [T]) Что означает consistency в распределённых системах?</p>\n","answer":"<p><strong>Ответ:</strong> Модель согласованности задаёт допустимые результаты и порядок наблюдения операций. Linearizable, sequential, causal и eventual описывают разные гарантии; это не ACID-инварианты.</p>\n<p><strong>Источник:</strong> <a href=\"https://jepsen.io/consistency\">Jepsen: Consistency models</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":27},{"id":"content/08_architecture_and_design/01_basic.md:a9c34aed4bc1b790:1","question":"<p>(L1 [T]) Что означает availability?</p>\n","answer":"<p><strong>Ответ:</strong> В CAP — каждый запрос к неотказавшему узлу получает ответ по правилам модели; ошибка вместо необходимого результата не решает противоречие. Пользовательская доступность по latency SLO — отдельная инженерная метрика.</p>\n<p><strong>Источник:</strong> <a href=\"https://groups.csail.mit.edu/tds/papers/Gilbert/Brewer2.pdf\">Gilbert, Lynch: Perspectives on CAP</a>; <a href=\"https://sre.google/sre-book/service-level-objectives/\">Google SRE: Service Level Objectives</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":33},{"id":"content/08_architecture_and_design/01_basic.md:fb8333bd6fb5d112:1","question":"<p>(L1 [T]) Что такое partition tolerance?</p>\n","answer":"<p><strong>Ответ:</strong> Способность системы продолжать работать согласно выбранным гарантиям при потере сообщений/связи между группами узлов. Во время разделения приходится ограничить доступность или ослабить согласованность.</p>\n<p><strong>Источник:</strong> <a href=\"https://groups.csail.mit.edu/tds/papers/Gilbert/Brewer2.pdf\">Gilbert, Lynch: Perspectives on CAP</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":39},{"id":"content/08_architecture_and_design/01_basic.md:b73f85cf26cfb8ec:1","question":"<p>(L1 [T]) Что такое latency?</p>\n","answer":"<p><strong>Ответ:</strong> Время между определёнными началом и завершением операции. Различают сетевой RTT, обработку и end-to-end latency; хвостовые процентили важнее одного среднего для многих сервисов.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/service-level-objectives/\">Google SRE: Service Level Objectives</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":45},{"id":"content/08_architecture_and_design/01_basic.md:e7899ce0cf0f0110:1","question":"<p>(L1 [T]) Что такое throughput?</p>\n","answer":"<p><strong>Ответ:</strong> Количество завершённой полезной работы за единицу времени: запросов/с, сообщений/с, байт/с. Измерять вместе с ошибками и latency, иначе рост входного потока маскирует перегрузку.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/handling-overload/\">Google SRE: Handling Overload</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":51},{"id":"content/08_architecture_and_design/01_basic.md:b8ef440025b1a588:1","question":"<p>(L1 [T]) Что такое idempotency?</p>\n","answer":"<p><strong>Ответ:</strong> Повтор операции имеет тот же задуманный эффект, что однократное выполнение. Ответ может отличаться; сетевой POST не является идемпотентным автоматически.</p>\n<p><strong>Пример:</strong> Повтор создания заказа с тем же idempotency key возвращает прежний заказ.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.rfc-editor.org/rfc/rfc9110.html\">RFC 9110: HTTP Semantics</a>; <a href=\"https://aws.amazon.com/builders-library/making-retries-safe-with-idempotent-APIs/\">AWS: Making retries safe with idempotent APIs</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":57},{"id":"content/08_architecture_and_design/01_basic.md:822c42310e3ca091:1","question":"<p>(L1 [T]) Что такое fault tolerance?</p>\n","answer":"<p><strong>Ответ:</strong> Сохранение требуемой функции при предусмотренных отказах компонентов. Нужны избыточность, изоляция, обнаружение и проверенное восстановление, а не только дополнительные узлы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/high-availability.html\">PostgreSQL: High Availability and Replication</a>; <a href=\"https://learn.microsoft.com/en-us/azure/architecture/patterns/bulkhead\">Azure Architecture: Bulkhead</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":65},{"id":"content/08_architecture_and_design/01_basic.md:4ae5bba399027ce3:1","question":"<p>(L1 [T]) Что такое horizontal scaling?</p>\n","answer":"<p><strong>Ответ:</strong> Добавление узлов и распределение нагрузки/данных между ними. Эффект ограничен общей БД, последовательной работой и коммуникацией.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/load-balancing-datacenter/\">Google SRE: Load Balancing in the Datacenter</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":71},{"id":"content/08_architecture_and_design/01_basic.md:61e48ea87486b3d8:1","question":"<p>(L1 [T]) Что такое vertical scaling?</p>\n","answer":"<p><strong>Ответ:</strong> Увеличение ресурсов одного узла: CPU, памяти, I/O и сети. Имеет предел аппаратной конфигурации и требует оценки доступности при изменении.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/handling-overload/\">Google SRE: Handling Overload</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":77},{"id":"content/08_architecture_and_design/01_basic.md:fb01a3e58773f001:1","question":"<p>(L2 [T]) В чём разница между strong consistency и eventual consistency?</p>\n","answer":"<p><strong>Ответ:</strong> Под strong часто понимают linearizability: чтение отражает завершённые записи в порядке реального времени. Eventual допускает временное расхождение и обещает сходимость при прекращении обновлений и восстановлении обмена.</p>\n<p><strong>Источник:</strong> <a href=\"https://jepsen.io/consistency\">Jepsen: Consistency models</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":84},{"id":"content/08_architecture_and_design/01_basic.md:248f1a4d32282e0c:1","question":"<p>(L2 [T]) Когда выбирают AP систему вместо CP?</p>\n","answer":"<p><strong>Ответ:</strong> Когда операция должна оставаться доступной при partition, а конфликты и устаревшие значения допустимы и разрешимы. Решение принимают по операциям, а не назначают один ярлык всей системе.</p>\n<p><strong>Пример:</strong> Лента рекомендаций допускает задержку, списание денег требует защиты инварианта.</p>\n<p><strong>Источник:</strong> <a href=\"https://groups.csail.mit.edu/tds/papers/Gilbert/Brewer2.pdf\">Gilbert, Lynch: Perspectives on CAP</a>; <a href=\"https://www.allthingsdistributed.com/files/amazon-dynamo-sosp2007.pdf\">Amazon Dynamo paper</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":90},{"id":"content/08_architecture_and_design/01_basic.md:679d2db444211188:1","question":"<p>(L2 [P]) Как реализовать idempotent API?</p>\n","answer":"<p><strong>Ответ:</strong> Принять ключ операции с fingerprint запроса, атомарно связать его с эффектом и сохранить результат. Повтор с тем же ключом возвращает сохранённый исход, с другим payload — отклоняется; concurrent запросы сериализуются.</p>\n<p><strong>Пример:</strong> UNIQUE(client_id, idempotency_key) защищает одновременное создание одного заказа.</p>\n<p><strong>Рекомендация:</strong> Задать окно хранения ключей не короче возможного окна повторов.</p>\n<p><strong>Источник:</strong> <a href=\"https://aws.amazon.com/builders-library/making-retries-safe-with-idempotent-APIs/\">AWS: Making retries safe with idempotent APIs</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":98},{"id":"content/08_architecture_and_design/01_basic.md:69b5a36847e78e45:1","question":"<p>(L2 [T]) Что такое quorum?</p>\n","answer":"<p><strong>Ответ:</strong> Набор участников, достаточный для принятия решения. В консенсусе обычно большинство; в leaderless модели задают R/W/N и пересечения. Пересечение само по себе не доказывает linearizability.</p>\n<p><strong>Пример:</strong> При N=3 большинство — 2.</p>\n<p><strong>Источник:</strong> <a href=\"https://raft.github.io/raft.pdf\">Raft paper</a>; <a href=\"https://www.allthingsdistributed.com/files/amazon-dynamo-sosp2007.pdf\">Amazon Dynamo paper</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":108},{"id":"content/08_architecture_and_design/01_basic.md:407b59f5b448fe38:1","question":"<p>(L2 [P]) Как уменьшить latency в распределённой системе?</p>\n","answer":"<p><strong>Ответ:</strong> Измерить critical path, очереди и сетевые RTT; сократить fan-out/hops, переиспользовать соединения и приблизить данные. Кэш и параллелизм применять с учётом свежести и нагрузки.</p>\n<p><strong>Источник:</strong> <a href=\"https://opentelemetry.io/docs/concepts/context-propagation/\">OpenTelemetry: Context propagation</a>; <a href=\"https://learn.microsoft.com/en-us/azure/architecture/patterns/cache-aside\">Azure Architecture: Cache-Aside</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":116},{"id":"content/08_architecture_and_design/01_basic.md:300c97b154cb8e28:1","question":"<p>(L2 [P]) Как увеличить throughput?</p>\n","answer":"<p><strong>Ответ:</strong> Найти насыщенный ресурс, затем оптимизировать запросы/алгоритм, batches и распараллеливание. Сохранять ограниченные очереди и проверять throughput при целевых p99 и доле ошибок.</p>\n<p><strong>Источник:</strong> <a href=\"https://sre.google/sre-book/handling-overload/\">Google SRE: Handling Overload</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":122},{"id":"content/08_architecture_and_design/01_basic.md:10679ba9c8240621:1","question":"<p>(L2 [T]) Что такое causal consistency?</p>\n","answer":"<p><strong>Ответ:</strong> Причинно связанные операции наблюдаются в причинном порядке; независимые могут иметь разный порядок на разных узлах. Не гарантирует единого глобального real-time порядка.</p>\n<p><strong>Пример:</strong> Ответ на сообщение не должен появляться раньше исходного сообщения.</p>\n<p><strong>Источник:</strong> <a href=\"https://jepsen.io/consistency\">Jepsen: Consistency models</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":128},{"id":"content/08_architecture_and_design/01_basic.md:72b30a700349c3a7:1","question":"<p>(L3 [D]) Как диагностировать split-brain?</p>\n","answer":"<p><strong>Ответ:</strong> Сопоставить одновременно активных лидеров, terms/epochs, membership и историю записей. Проверить partition, lease и fencing; при восстановлении не сливать конфликтующие журналы вслепую.</p>\n<p><strong>Источник:</strong> <a href=\"https://raft.github.io/raft.pdf\">Raft paper</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":137},{"id":"content/08_architecture_and_design/01_basic.md:ae8d73badf55226a:1","question":"<p>(L3 [T]) Как работают distributed locks?</p>\n","answer":"<p><strong>Ответ:</strong> Участник получает право работать с ресурсом через согласованный сервис координации, часто с lease. Потерявший lease процесс может продолжить работу, поэтому ресурс должен проверять монотонный fencing token.</p>\n<p><strong>Типичная ошибка:</strong> Полагаться только на TTL блокировки без защиты от «ожившего» старого владельца.</p>\n<p><strong>Источник:</strong> <a href=\"https://raft.github.io/raft.pdf\">Raft paper</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":143},{"id":"content/08_architecture_and_design/01_basic.md:66e816542fb09a74:1","question":"<p>(L3 [P]) Как реализовать retry с exponential backoff?</p>\n","answer":"<p><strong>Ответ:</strong> Пауза перед попыткой n: random(0, min(cap, base×2^n)); ограничить attempts и общий deadline. Повторять лишь временные ошибки и безопасные операции, учитывать Retry-After.</p>\n<p><strong>Пример:</strong> base=100 мс, cap=2 с; full jitter распределяет клиентов по времени.</p>\n<p><strong>Источник:</strong> <a href=\"https://aws.amazon.com/builders-library/timeouts-retries-and-backoff-with-jitter/\">AWS: Timeouts, retries, backoff and jitter</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":151},{"id":"content/08_architecture_and_design/01_basic.md:5cfa0c6babb77616:1","question":"<p>(L3 [T]) Как clock skew влияет на систему?</p>\n","answer":"<p><strong>Ответ:</strong> Смещение часов и скачки wall clock искажают timestamps, TTL, leases и порядок событий. Для локальных интервалов использовать monotonic clock, для распределённого порядка — версии/логические часы или согласованный протокол.</p>\n<p><strong>Типичная ошибка:</strong> Считать NTP гарантией строгого глобального порядка.</p>\n<p><strong>Источник:</strong> <a href=\"https://raft.github.io/raft.pdf\">Raft paper</a>; <a href=\"https://jepsen.io/consistency\">Jepsen: Consistency models</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":159},{"id":"content/08_architecture_and_design/01_basic.md:9f89f6b2ee581e8f:1","question":"<p>(L3 [D]) Почему система теряет consistency?</p>\n","answer":"<p><strong>Ответ:</strong> Сначала определить нарушенный инвариант и собрать историю операций. Проверить stale replica reads, lost updates, split-brain, weak isolation и конфликты multi-writer; сравнить с обещанной моделью.</p>\n<p><strong>Источник:</strong> <a href=\"https://jepsen.io/consistency\">Jepsen: Consistency models</a>; <a href=\"https://www.postgresql.org/docs/current/mvcc.html\">PostgreSQL: Concurrency Control</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":167},{"id":"content/08_architecture_and_design/01_basic.md:fe6c802dd328892a:1","question":"<p>(L4 [S]) Как выбрать consistency model для банковской системы?</p>\n","answer":"<p><strong>Ответ:</strong> Разделить операции: ledger и переводы защищать транзакциями с подходящей изоляцией, уникальными operation IDs и аудитом; витрины/уведомления обновлять асинхронно. Serializable и real-time freshness — разные свойства, их задают явно.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/mvcc.html\">PostgreSQL: Concurrency Control</a>; <a href=\"https://jepsen.io/consistency\">Jepsen: Consistency models</a>; <a href=\"https://aws.amazon.com/builders-library/making-retries-safe-with-idempotent-APIs/\">AWS: Making retries safe with idempotent APIs</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":174},{"id":"content/08_architecture_and_design/01_basic.md:56cde48296ecf958:1","question":"<p>(L4 [S]) Как спроектировать geo-distributed систему?</p>\n","answer":"<p><strong>Ответ:</strong> Определить SLO, data residency, home region, RPO/RTO и partition policy. Строгие данные координировать через quorum, допустимые проекции реплицировать асинхронно; проверить отказ региона и запас capacity.</p>\n<p><strong>Источник:</strong> <a href=\"https://learn.microsoft.com/en-us/azure/architecture/patterns/deployment-stamp\">Azure Architecture: Deployment stamps</a>; <a href=\"https://raft.github.io/raft.pdf\">Raft paper</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":180},{"id":"content/08_architecture_and_design/01_basic.md:bec37493e106ae6a:1","question":"<p>(L4 [S]) Когда допустима eventual consistency?</p>\n","answer":"<p><strong>Ответ:</strong> Когда продукт принимает временную устарелость, конфликты разрешимы и критичные инварианты защищены отдельно. Нужны repair/reconciliation, измерение lag и определённое поведение read-your-writes.</p>\n<p><strong>Пример:</strong> Счётчик просмотров, поиск и рекомендации часто допускают задержку.</p>\n<p><strong>Источник:</strong> <a href=\"https://jepsen.io/consistency\">Jepsen: Consistency models</a>; <a href=\"https://www.allthingsdistributed.com/files/amazon-dynamo-sosp2007.pdf\">Amazon Dynamo paper</a></p>\n","group":"🧠 1. Базовые принципы распределённых систем","line":186},{"id":"content/08_architecture_and_design/01_basic.md:8ef7f974699891e8:1","question":"<p>(L1 [T]) Что такое SQL?</p>\n","answer":"<p><strong>Ответ:</strong> SQL — декларативный язык определения, запроса и изменения данных, обычно реляционных. Стандарт SQL и поддерживаемые расширения различаются у СУБД.</p>\n<p><strong>Пример:</strong> SELECT id FROM users WHERE active = true;</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/\">PostgreSQL: Documentation</a></p>\n","group":"🗄️ 2. Хранение данных","line":199},{"id":"content/08_architecture_and_design/01_basic.md:ebb546998f4c8a5c:1","question":"<p>(L1 [T]) Что такое NoSQL?</p>\n","answer":"<p><strong>Ответ:</strong> SQL — язык работы с данными, обычно в реляционной модели; NoSQL объединяет документные, key-value, графовые и другие модели. Транзакции и масштабирование зависят от конкретной СУБД.</p>\n<p><strong>Типичная ошибка:</strong> Считать, что NoSQL всегда лишён схемы и транзакций.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/\">PostgreSQL: Documentation</a></p>\n","group":"🗄️ 2. Хранение данных","line":207},{"id":"content/08_architecture_and_design/01_basic.md:a11148d0e9cddcea:1","question":"<p>(L1 [T]) Что такое индекс?</p>\n","answer":"<p><strong>Ответ:</strong> Дополнительная структура для ускорения поиска, сортировки или проверки уникальности. Занимает место и увеличивает стоимость записи.</p>\n<p><strong>Пример:</strong> Индекс по user_id ускоряет выборку заказов пользователя.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a></p>\n","group":"🗄️ 2. Хранение данных","line":215},{"id":"content/08_architecture_and_design/01_basic.md:c78f005cf30df2f5:1","question":"<p>(L1 [T]) Что такое primary key?</p>\n","answer":"<p><strong>Ответ:</strong> Primary key однозначно идентифицирует строку: значения уникальны и не NULL. Может быть составным; физический порядок хранения зависит от СУБД.</p>\n<p><strong>Пример:</strong> PRIMARY KEY (tenant_id, order_id).</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/\">PostgreSQL: Documentation</a>; <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a></p>\n","group":"🗄️ 2. Хранение данных","line":223},{"id":"content/08_architecture_and_design/01_basic.md:493e73c473ffe10e:1","question":"<p>(L1 [T]) Что такое replication?</p>\n","answer":"<p><strong>Ответ:</strong> Поддержание копий данных на нескольких узлах. Репликация бывает синхронной и асинхронной; помогает доступности и чтению, но не заменяет резервные копии.</p>\n<p><strong>Типичная ошибка:</strong> Удаление данных может реплицироваться на все узлы.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/high-availability.html\">PostgreSQL: High Availability and Replication</a></p>\n","group":"🗄️ 2. Хранение данных","line":231},{"id":"content/08_architecture_and_design/01_basic.md:b3bace1e2dedc030:1","question":"<p>(L1 [T]) Что такое sharding?</p>\n","answer":"<p><strong>Ответ:</strong> Часть горизонтально разделённого набора данных, закреплённая за узлом или группой реплик. Shard — часть данных, replica — копия.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/ddl-partitioning.html\">PostgreSQL: Table Partitioning</a>; <a href=\"https://redis.io/docs/latest/operate/oss_and_stack/reference/cluster-spec/\">Redis: Cluster specification</a></p>\n","group":"🗄️ 2. Хранение данных","line":239},{"id":"content/08_architecture_and_design/01_basic.md:865d656f74968008:1","question":"<p>(L2 [T]) В чём разница между B-Tree и LSM Tree?</p>\n","answer":"<p><strong>Ответ:</strong> B-tree обновляет страницы дерева и удобен для точечных/диапазонных чтений; LSM буферизует запись и объединяет отсортированные файлы. LSM платит compaction и amplification, B-tree — своими затратами случайных изменений страниц.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://github.com/facebook/rocksdb/wiki/RocksDB-Overview\">RocksDB: Overview</a></p>\n","group":"🗄️ 2. Хранение данных","line":246},{"id":"content/08_architecture_and_design/01_basic.md:c5908d9f14e925e0:1","question":"<p>(L2 [P]) Как выбрать тип базы данных?</p>\n","answer":"<p><strong>Ответ:</strong> Зафиксировать инварианты, запросы, объёмы, RPO/RTO и навыки команды; сравнить кандидатов на реалистичных данных и отказах. Проверить миграции и стоимость сопровождения.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/\">PostgreSQL: Documentation</a>; <a href=\"https://www.allthingsdistributed.com/files/amazon-dynamo-sosp2007.pdf\">Amazon Dynamo paper</a></p>\n","group":"🗄️ 2. Хранение данных","line":252},{"id":"content/08_architecture_and_design/01_basic.md:323691dc2689eb72:1","question":"<p>(L2 [T]) Что такое leader-follower replication?</p>\n","answer":"<p><strong>Ответ:</strong> Лидер принимает изменения и передаёт их followers. Followers обслуживают разрешённые чтения и могут участвовать в failover; свежесть зависит от режима репликации.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/high-availability.html\">PostgreSQL: High Availability and Replication</a></p>\n","group":"🗄️ 2. Хранение данных","line":258},{"id":"content/08_architecture_and_design/01_basic.md:20b02f87e67e6fc8:1","question":"<p>(L2 [P]) Как работает sharding?</p>\n","answer":"<p><strong>Ответ:</strong> Выбрать ключ из основных запросов, оценить кардинальность, перекос, рост и межшардовые транзакции. Заранее определить маршрутизацию и процедуру split/move.</p>\n<p><strong>Типичная ошибка:</strong> Шардировать только по времени при монотонном потоке записей.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/ddl-partitioning.html\">PostgreSQL: Table Partitioning</a>; <a href=\"https://www.allthingsdistributed.com/files/amazon-dynamo-sosp2007.pdf\">Amazon Dynamo paper</a></p>\n","group":"🗄️ 2. Хранение данных","line":264},{"id":"content/08_architecture_and_design/01_basic.md:bec685dcf36c2894:1","question":"<p>(L2 [T]) Что такое ACID?</p>\n","answer":"<p><strong>Ответ:</strong> Atomicity, Consistency, Isolation, Durability — свойства транзакций: целостное применение, сохранение инвариантов, изоляция и сохранность подтверждённых результатов.</p>\n<p><strong>Типичная ошибка:</strong> Путать ACID consistency с согласованностью реплик CAP.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/mvcc.html\">PostgreSQL: Concurrency Control</a></p>\n","group":"🗄️ 2. Хранение данных","line":272},{"id":"content/08_architecture_and_design/01_basic.md:185b9d789bd44529:1","question":"<p>(L2 [T]) Что такое BASE?</p>\n","answer":"<p><strong>Ответ:</strong> Basically Available, Soft state, Eventual consistency — подход, допускающий временное расхождение ради доступности. Это не строгая спецификация транзакций и не синоним любой NoSQL БД.</p>\n<p><strong>Источник:</strong> <a href=\"https://queue.acm.org/detail.cfm?id=1394128\">Pritchett: BASE, an ACID Alternative</a></p>\n","group":"🗄️ 2. Хранение данных","line":280},{"id":"content/08_architecture_and_design/01_basic.md:7a376207e636f780:1","question":"<p>(L3 [D]) Почему запрос внезапно стал медленным?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить планы до/после, оценки строк, статистику и BUFFERS. Новый индекс может привести к неудачному плану; на записи он добавляет работу, а создание может конкурировать за I/O.</p>\n<p><strong>Типичная ошибка:</strong> Удалять индекс без сравнения плана и профиля нагрузки.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/using-explain.html\">PostgreSQL: Using EXPLAIN</a></p>\n","group":"🗄️ 2. Хранение данных","line":287},{"id":"content/08_architecture_and_design/01_basic.md:5a9136a9a48c52af:1","question":"<p>(L3 [T]) Как работает MVCC?</p>\n","answer":"<p><strong>Ответ:</strong> MVCC хранит версии строк; снимок и правила изоляции определяют видимую версию. Старые версии очищаются после исчезновения потребности в них; долгие транзакции мешают очистке.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/mvcc.html\">PostgreSQL: Concurrency Control</a></p>\n","group":"🗄️ 2. Хранение данных","line":295},{"id":"content/08_architecture_and_design/01_basic.md:42d21176999fa89d:1","question":"<p>(L3 [P]) Как мигрировать данные без даунтайма?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать expand–migrate–contract: совместимая схема, backfill малыми партиями, перенос изменений через CDC/outbox, сверка, переключение чтений и лишь затем удаление старого. Предусмотреть rollback и ограничение нагрузки.</p>\n<p><strong>Типичная ошибка:</strong> Считать две независимые записи в старое и новое хранилище атомарными.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/\">PostgreSQL: Documentation</a>; <a href=\"https://www.postgresql.org/docs/current/high-availability.html\">PostgreSQL: High Availability and Replication</a></p>\n","group":"🗄️ 2. Хранение данных","line":301},{"id":"content/08_architecture_and_design/01_basic.md:4b10555c694bf9f7:1","question":"<p>(L3 [D]) Как обнаружить hot shard?</p>\n","answer":"<p><strong>Ответ:</strong> Сравнить QPS, объём, p99, CPU, I/O и очереди по shard и по ключам. Отличить один горячий ключ от неравномерного распределения множества ключей.</p>\n<p><strong>Источник:</strong> <a href=\"https://redis.io/docs/latest/operate/oss_and_stack/management/optimization/latency/\">Redis: Latency diagnosis</a>; <a href=\"https://www.postgresql.org/docs/current/ddl-partitioning.html\">PostgreSQL: Table Partitioning</a></p>\n","group":"🗄️ 2. Хранение данных","line":309},{"id":"content/08_architecture_and_design/01_basic.md:0ecf7f825af39f67:1","question":"<p>(L3 [P]) Как реализовать consistent hashing?</p>\n","answer":"<p><strong>Ответ:</strong> Хэшировать виртуальные узлы и ключи в одно упорядоченное пространство, выбрать первый токен по часовой стрелке с обходом конца. Хранить версию карты и план переноса; для реплик выбирать разные физические узлы.</p>\n<p><strong>Пример:</strong> Для токенов [20, 60, 90] ключ 61 назначается владельцу 90.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.allthingsdistributed.com/files/amazon-dynamo-sosp2007.pdf\">Amazon Dynamo paper</a></p>\n","group":"🗄️ 2. Хранение данных","line":315},{"id":"content/08_architecture_and_design/01_basic.md:8c2f4ddfd4c7b4bf:1","question":"<p>(L4 [S]) Как спроектировать storage для миллиарда пользователей?</p>\n","answer":"<p><strong>Ответ:</strong> Оценить активных пользователей, QPS, размеры и retention; выделить транзакционный источник истины, объектное хранилище и аналитические проекции. Шардировать по локальности запросов, спланировать реплики, backup/restore и rebalance.</p>\n<p><strong>Типичная ошибка:</strong> Само число зарегистрированных пользователей не определяет архитектуру.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/ddl-partitioning.html\">PostgreSQL: Table Partitioning</a>; <a href=\"https://www.postgresql.org/docs/current/high-availability.html\">PostgreSQL: High Availability and Replication</a></p>\n","group":"🗄️ 2. Хранение данных","line":324},{"id":"content/08_architecture_and_design/01_basic.md:272e61158b9c3ff5:1","question":"<p>(L4 [S]) Когда использовать multi-leader replication?</p>\n","answer":"<p><strong>Ответ:</strong> Когда нескольким регионам нужна локальная запись либо поддержка offline, а конфликты можно детектировать и разрешать. Для уникальности, баланса и других глобальных инвариантов нужна дополнительная координация.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/high-availability.html\">PostgreSQL: High Availability and Replication</a>; <a href=\"https://www.allthingsdistributed.com/files/amazon-dynamo-sosp2007.pdf\">Amazon Dynamo paper</a></p>\n","group":"🗄️ 2. Хранение данных","line":332},{"id":"content/08_architecture_and_design/01_basic.md:48334f7929e2dd1a:1","question":"<p>(L4 [S]) Как минимизировать cross-shard запросы?</p>\n","answer":"<p><strong>Ответ:</strong> Размещать связанные данные по tenant/user/aggregate, денормализовать нужные представления и выполнять аналитику отдельно. Глобальные запросы делать явными, с ограничением fan-out.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.postgresql.org/docs/current/ddl-partitioning.html\">PostgreSQL: Table Partitioning</a></p>\n","group":"🗄️ 2. Хранение данных","line":338},{"id":"content/08_architecture_and_design/01_basic.md:5bb0b2177450619c:1","question":"<p>(L1 [T]) Что такое процесс?</p>\n","answer":"<p><strong>Ответ:</strong> Экземпляр выполняющейся программы с адресным пространством, ресурсами и одним или несколькими потоками. PID идентифицирует процесс в пределах соответствующего namespace.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/credentials.7.html\">Linux man-pages: credentials and process attributes</a></p>\n","group":"🐧 3. Linux internals","line":349},{"id":"content/08_architecture_and_design/01_basic.md:87e0b2d69544c2df:1","question":"<p>(L1 [T]) Что такое поток?</p>\n","answer":"<p><strong>Ответ:</strong> Поток исполнения внутри процесса со своим стеком и регистровым состоянием; разделяет адресное пространство и многие ресурсы с другими потоками процесса.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/pthreads.7.html\">Linux man-pages: pthreads</a></p>\n","group":"🐧 3. Linux internals","line":355},{"id":"content/08_architecture_and_design/01_basic.md:455c30234706b707:1","question":"<p>(L1 [T]) Что такое syscall?</p>\n","answer":"<p><strong>Ответ:</strong> Вход из userspace в ядро для привилегированной операции через заданный ABI. Обёртка libc не всегда равна одному syscall, а некоторые функции обслуживаются через vDSO.</p>\n<p><strong>Пример:</strong> read, write, mmap.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/syscalls.2.html\">Linux man-pages: syscalls</a></p>\n","group":"🐧 3. Linux internals","line":361},{"id":"content/08_architecture_and_design/01_basic.md:d0e3551c87df7aee:1","question":"<p>(L1 [T]) Что такое file descriptor?</p>\n","answer":"<p><strong>Ответ:</strong> Небольшое целое, индекс в таблице открытых ресурсов процесса. FD ссылается на open file description; dup/fork могут разделять позицию файла.</p>\n<p><strong>Типичная ошибка:</strong> Путать номер fd с устойчивым идентификатором файла.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/open.2.html\">Linux man-pages: open</a></p>\n","group":"🐧 3. Linux internals","line":369},{"id":"content/08_architecture_and_design/01_basic.md:f6eb51c50aaefd86:1","question":"<p>(L1 [T]) Что такое virtual memory?</p>\n","answer":"<p><strong>Ответ:</strong> Абстракция адресного пространства с отображением виртуальных страниц на физические страницы/файлы. Позволяет изоляцию и совместное использование; виртуальный объём не равен RSS.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/admin-guide/mm/concepts.html\">Linux kernel: Memory management concepts</a></p>\n","group":"🐧 3. Linux internals","line":377},{"id":"content/08_architecture_and_design/01_basic.md:763e716d5e7ec312:1","question":"<p>(L2 [P]) Как работает fork()?</p>\n","answer":"<p><strong>Ответ:</strong> Создаёт дочерний процесс; в родителе возвращает PID ребёнка, в ребёнке 0, при ошибке −1. Память обычно copy-on-write, FD наследуются; после fork многопоточного процесса до exec безопасны только async-signal-safe операции.</p>\n<p><strong>Типичная ошибка:</strong> Повторно flush одинаковых stdio buffers в обоих процессах.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">Linux man-pages: fork</a></p>\n","group":"🐧 3. Linux internals","line":384},{"id":"content/08_architecture_and_design/01_basic.md:7e11268ebd01a4af:1","question":"<p>(L2 [T]) Что такое context switch?</p>\n","answer":"<p><strong>Ответ:</strong> Сохранение состояния исполняемой задачи и восстановление другой при передаче CPU. Цена включает scheduler work и потенциальную потерю locality кэшей/TLB; переход в kernel mode сам по себе не обязательно переключает задачу.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/scheduler/sched-eevdf.html\">Linux kernel: EEVDF scheduler</a></p>\n","group":"🐧 3. Linux internals","line":392},{"id":"content/08_architecture_and_design/01_basic.md:ef04b9db0d3d8341:1","question":"<p>(L2 [P]) Как работает mmap()?</p>\n","answer":"<p><strong>Ответ:</strong> Создаёт отображение файла либо anonymous memory в адресном пространстве. Проверять MAP_FAILED, размер/защиту и различие MAP_SHARED/MAP_PRIVATE; доступ может вызвать page fault.</p>\n<p><strong>Пример:</strong> mmap(nullptr, length, PROT_READ, MAP_PRIVATE, fd, 0) отображает файл для чтения.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/mmap.2.html\">Linux man-pages: mmap</a></p>\n","group":"🐧 3. Linux internals","line":398},{"id":"content/08_architecture_and_design/01_basic.md:03e5e2a6ca52d4c4:1","question":"<p>(L2 [T]) Что такое page fault?</p>\n","answer":"<p><strong>Ответ:</strong> Исключение при доступе к странице, для которой нужно установить/изменить отображение либо проверить права. Minor fault не требует чтения с диска, major обычно требует I/O; недопустимый доступ может завершиться SIGSEGV.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/admin-guide/mm/concepts.html\">Linux kernel: Memory management concepts</a></p>\n","group":"🐧 3. Linux internals","line":406},{"id":"content/08_architecture_and_design/01_basic.md:8c7626b00b972545:1","question":"<p>(L2 [T]) Что такое copy-on-write?</p>\n","answer":"<p><strong>Ответ:</strong> Совместное использование страниц до первой записи; при записи создаётся отдельная копия. После fork это экономит память, но объём приватных страниц растёт при изменениях.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/fork.2.html\">Linux man-pages: fork</a>; <a href=\"https://docs.kernel.org/admin-guide/mm/concepts.html\">Linux kernel: Memory management concepts</a></p>\n","group":"🐧 3. Linux internals","line":412},{"id":"content/08_architecture_and_design/01_basic.md:5bf289f58591f425:1","question":"<p>(L3 [D]) Почему процесс потребляет 100% CPU?</p>\n","answer":"<p><strong>Ответ:</strong> Найти горячие threads и stacks через top -H/perf, разделить user/system и полезную работу от spin/retry loop. Проверить контейнерную CPU quota и единицу измерения: 100% часто означает одно ядро.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man1/perf-record.1.html\">Linux perf: perf record</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"🐧 3. Linux internals","line":419},{"id":"content/08_architecture_and_design/01_basic.md:d94bc98c87eb15ec:1","question":"<p>(L3 [D]) Как найти memory leak?</p>\n","answer":"<p><strong>Ответ:</strong> Сначала подтвердить растущий live heap, а не кэш/fragmentation/RSS; сравнить heap snapshots и allocation stacks. Для C/C++ использовать LeakSanitizer в воспроизводимом сценарии и проверить жизненный цикл владельцев.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/LeakSanitizer.html\">Clang: LeakSanitizer</a>; <a href=\"https://isocpp.github.io/CppCoreGuidelines/CppCoreGuidelines#S-resource\">C++ Core Guidelines: Resource management</a></p>\n","group":"🐧 3. Linux internals","line":425},{"id":"content/08_architecture_and_design/01_basic.md:88b2f4d13bee7b5c:1","question":"<p>(L3 [P]) Как работает scheduler?</p>\n","answer":"<p><strong>Ответ:</strong> Планировщик выбирает runnable задачи с учётом scheduling class, приоритета и fairness/deadlines. В современных ядрах Linux fair scheduling развивается от CFS к EEVDF; поведение зависит от версии, CPU affinity и cgroups.</p>\n<p><strong>Типичная ошибка:</strong> Описывать все версии Linux как неизменно использующие только классический CFS.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/scheduler/sched-eevdf.html\">Linux kernel: EEVDF scheduler</a></p>\n","group":"🐧 3. Linux internals","line":431},{"id":"content/08_architecture_and_design/01_basic.md:62a6275bec33e5a2:1","question":"<p>(L3 [T]) Что такое NUMA?</p>\n","answer":"<p><strong>Ответ:</strong> Non-Uniform Memory Access: CPU быстрее обращается к локально подключённой памяти, чем к памяти другого NUMA-узла. Важны размещение потоков и first-touch allocation.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/admin-guide/mm/numa_memory_policy.html\">Linux kernel: NUMA memory policy</a></p>\n","group":"🐧 3. Linux internals","line":439},{"id":"content/08_architecture_and_design/01_basic.md:b2a5f98087c7afee:1","question":"<p>(L3 [D]) Как анализировать OOM killer?</p>\n","answer":"<p><strong>Ответ:</strong> Изучить kernel/journal сообщения, victim, memory pressure, swap и ограничения cgroup. Сопоставить memory.current/max/events и состав RSS; причина может быть лимитом контейнера, а не исчерпанием всей RAM.</p>\n<p><strong>Типичная ошибка:</strong> Увеличивать лимит до выяснения роста памяти и working set.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/admin-guide/cgroup-v2.html#memory\">Linux kernel: cgroup v2 memory controller</a></p>\n","group":"🐧 3. Linux internals","line":445},{"id":"content/08_architecture_and_design/01_basic.md:4933eab1999fc7c2:1","question":"<p>(L4 [S]) Как тюнить Linux под high-load?</p>\n","answer":"<p><strong>Ответ:</strong> Измерить bottleneck через CPU/I/O/network/queues, затем менять конкретный лимит с baseline и rollback. Проверять tail latency, ресурсы cgroup, IRQ и пулы; универсального набора sysctl для high-load нет.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a>; <a href=\"https://sre.google/sre-book/handling-overload/\">Google SRE: Handling Overload</a></p>\n","group":"🐧 3. Linux internals","line":454},{"id":"content/08_architecture_and_design/01_basic.md:e1912fee103ca6d8:1","question":"<p>(L4 [S]) Как оптимизировать NUMA workload?</p>\n","answer":"<p><strong>Ответ:</strong> Размещать worker и его данные на одном NUMA node, контролировать affinity и memory policy. Для общего набора сравнить interleave с локализацией, проверить remote accesses и баланс нагрузки.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/admin-guide/mm/numa_memory_policy.html\">Linux kernel: NUMA memory policy</a></p>\n","group":"🐧 3. Linux internals","line":460},{"id":"content/08_architecture_and_design/01_basic.md:5dbe45298e8b1fd7:1","question":"<p>(L4 [S]) Когда использовать huge pages?</p>\n","answer":"<p><strong>Ответ:</strong> Когда большой рабочий набор страдает от TLB misses и экономия подтверждена измерениями. Учесть резервирование, внутреннюю фрагментацию и особенности THP/HugeTLB; большие страницы не исправляют плохую locality.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.kernel.org/admin-guide/mm/hugetlbpage.html\">Linux kernel: HugeTLB pages</a>; <a href=\"https://docs.kernel.org/admin-guide/mm/numa_memory_policy.html\">Linux kernel: NUMA memory policy</a></p>\n","group":"🐧 3. Linux internals","line":466},{"id":"content/08_architecture_and_design/01_basic.md:7ef42e66c27d48a9:1","question":"<p>(L1 [T]) Что такое TCP?</p>\n","answer":"<p><strong>Ответ:</strong> Надёжный упорядоченный поток байтов поверх IP с контролем потока и перегрузки. Не сохраняет границы сообщений приложения и не гарантирует, что peer обработал принятые данные.</p>\n<p><strong>Типичная ошибка:</strong> Считать один recv одним сообщением.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.rfc-editor.org/rfc/rfc9293.html\">RFC 9293: TCP</a></p>\n","group":"🌐 4. Networking","line":477},{"id":"content/08_architecture_and_design/01_basic.md:f1aacb2dae03ce7e:1","question":"<p>(L1 [T]) Что такое UDP?</p>\n","answer":"<p><strong>Ответ:</strong> Протокол датаграмм без встроенной гарантии доставки, порядка и повторной передачи. Приложение само определяет обработку потерь и congestion control.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.rfc-editor.org/rfc/rfc768.html\">RFC 768: UDP</a></p>\n","group":"🌐 4. Networking","line":485},{"id":"content/08_architecture_and_design/01_basic.md:02f648dd4015c15f:1","question":"<p>(L1 [T]) Что такое socket?</p>\n","answer":"<p><strong>Ответ:</strong> Endpoint сетевого взаимодействия, представленный API/дескриптором. Тип и семейство задают stream/datagram и адресацию.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/socket.2.html\">Linux man-pages: socket</a></p>\n","group":"🌐 4. Networking","line":491},{"id":"content/08_architecture_and_design/01_basic.md:b353dac6b6152b89:1","question":"<p>(L1 [T]) Что такое DNS?</p>\n","answer":"<p><strong>Ответ:</strong> Распределённая иерархическая система записей доменных имён с кэшированием по TTL. Разрешает не только IP-адреса: существуют MX, TXT, SRV и другие записи.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.rfc-editor.org/rfc/rfc1034.html\">RFC 1034: Domain names</a></p>\n","group":"🌐 4. Networking","line":497},{"id":"content/08_architecture_and_design/01_basic.md:edfde099f8ba96c6:1","question":"<p>(L2 [T]) Как работает TCP handshake?</p>\n","answer":"<p><strong>Ответ:</strong> Клиент посылает SYN, сервер отвечает SYN-ACK, клиент подтверждает ACK. Стороны синхронизируют sequence numbers; TLS при HTTPS — отдельный последующий протокол.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.rfc-editor.org/rfc/rfc9293.html\">RFC 9293: TCP</a></p>\n","group":"🌐 4. Networking","line":504},{"id":"content/08_architecture_and_design/01_basic.md:02d9a1640d53a3d5:1","question":"<p>(L2 [P]) Как написать TCP сервер?</p>\n","answer":"<p><strong>Ответ:</strong> socket → bind → listen → accept, затем цикл read/write с framing и обработкой ошибок. Для конкурентных клиентов выбрать threads/event loop; учитывать partial I/O, EOF, EINTR/EAGAIN и лимиты.</p>\n<p><strong>Пример:</strong> Сначала читать заголовок длины, затем ровно указанное допустимое число байтов.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/socket.2.html\">Linux man-pages: socket</a>; <a href=\"https://www.rfc-editor.org/rfc/rfc9293.html\">RFC 9293: TCP</a></p>\n","group":"🌐 4. Networking","line":510},{"id":"content/08_architecture_and_design/01_basic.md:2e316078fd35ac99:1","question":"<p>(L2 [T]) Что такое epoll?</p>\n","answer":"<p><strong>Ответ:</strong> Linux API готовности множества FD: создать instance, зарегистрировать интерес и ждать events. В edge-triggered режиме nonblocking I/O обычно нужно вычитывать/записывать до EAGAIN.</p>\n<p><strong>Типичная ошибка:</strong> Считать readiness гарантией, что следующее I/O не вернёт EAGAIN.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">Linux man-pages: epoll</a></p>\n","group":"🌐 4. Networking","line":518},{"id":"content/08_architecture_and_design/01_basic.md:ad7ab6a9e1cca523:1","question":"<p>(L2 [T]) Что такое keep-alive?</p>\n","answer":"<p><strong>Ответ:</strong> TCP keepalive — опциональные пробы простаивающего соединения, HTTP keep-alive — reuse для нескольких запросов. Настройки и назначение различаются; прикладной heartbeat может давать более точный сигнал.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.rfc-editor.org/rfc/rfc9293.html\">RFC 9293: TCP</a>; <a href=\"https://www.rfc-editor.org/rfc/rfc9110.html\">RFC 9110: HTTP Semantics</a></p>\n","group":"🌐 4. Networking","line":526},{"id":"content/08_architecture_and_design/01_basic.md:ca4c7a43c80150b4:1","question":"<p>(L3 [D]) Почему connection reset by peer?</p>\n","answer":"<p><strong>Ответ:</strong> Соединение было сброшено RST другой стороной или промежуточным устройством. Сопоставить packet capture, server/LB logs, idle timeout и момент закрытия; не считать это доказательством ошибки только удалённого приложения.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.rfc-editor.org/rfc/rfc9293.html\">RFC 9293: TCP</a></p>\n","group":"🌐 4. Networking","line":533},{"id":"content/08_architecture_and_design/01_basic.md:e099f2bdfab263d6:1","question":"<p>(L3 [D]) Как диагностировать packet loss?</p>\n","answer":"<p><strong>Ответ:</strong> Сопоставить end-to-end retransmits, NIC drops/errors, очереди и captures на обеих сторонах. Loss ответа промежуточного hop в mtr не доказывает потерю транзитного трафика из-за ICMP rate limiting.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.rfc-editor.org/rfc/rfc9293.html\">RFC 9293: TCP</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"🌐 4. Networking","line":539},{"id":"content/08_architecture_and_design/01_basic.md:49cae094e79107d2:1","question":"<p>(L3 [P]) Как работает zero-copy (sendfile)?</p>\n","answer":"<p><strong>Ответ:</strong> Передаёт данные между поддерживаемыми FD без копирования payload через userspace. Нужно обрабатывать короткую отправку/ошибки, а наличие «zero-copy» не гарантирует отсутствие любых копий внутри kernel/hardware.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man2/sendfile.2.html\">Linux man-pages: sendfile</a></p>\n","group":"🌐 4. Networking","line":545},{"id":"content/08_architecture_and_design/01_basic.md:1952c9014672fc2f:1","question":"<p>(L3 [T]) Что такое congestion control?</p>\n","answer":"<p><strong>Ответ:</strong> Регулирование интенсивности отправки по состоянию сети, чтобы не перегружать маршрут. Отличается от flow control, защищающего приёмный буфер получателя.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.rfc-editor.org/rfc/rfc5681.html\">RFC 5681: TCP Congestion Control</a></p>\n","group":"🌐 4. Networking","line":551},{"id":"content/08_architecture_and_design/01_basic.md:ec6671dc7ccc5c74:1","question":"<p>(L4 [S]) Как оптимизировать сетевой стек?</p>\n","answer":"<p><strong>Ответ:</strong> Сначала измерить packets/bytes, RTT, loss, softirq, backlog и NIC queues. Затем проверять RSS/RPS, affinity, offload, буферы и connection reuse на конкретной нагрузке с rollback.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a>; <a href=\"https://www.rfc-editor.org/rfc/rfc9293.html\">RFC 9293: TCP</a></p>\n","group":"🌐 4. Networking","line":558},{"id":"content/08_architecture_and_design/01_basic.md:830b57008b0dab8f:1","question":"<p>(L4 [S]) Когда использовать UDP вместо TCP?</p>\n","answer":"<p><strong>Ответ:</strong> Когда допустимы потери/устаревшие данные либо приложение реализует нужную надёжность и ordering. QUIC использует UDP, но сам добавляет надёжные streams и congestion control.</p>\n<p><strong>Пример:</strong> Realtime медиа часто предпочитает своевременный пакет запоздалому retransmit.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.rfc-editor.org/rfc/rfc768.html\">RFC 768: UDP</a>; <a href=\"https://www.rfc-editor.org/rfc/rfc5681.html\">RFC 5681: TCP Congestion Control</a></p>\n","group":"🌐 4. Networking","line":564},{"id":"content/08_architecture_and_design/01_basic.md:26f0b1ed6d5c51c5:1","question":"<p>(L4 [S]) Как проектировать high-load network service?</p>\n","answer":"<p><strong>Ответ:</strong> Nonblocking I/O или ограниченные worker pools, явный framing, deadlines, connection limits и backpressure. Проверять slow clients, bursts, TLS, partial I/O и graceful shutdown, а ёмкость считать по CPU, FD, памяти и сети.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man7/epoll.7.html\">Linux man-pages: epoll</a>; <a href=\"https://sre.google/sre-book/handling-overload/\">Google SRE: Handling Overload</a></p>\n","group":"🌐 4. Networking","line":572},{"id":"content/08_architecture_and_design/01_basic.md:f68bc9cd30e70969:1","question":"<p>(L1 [T]) Что такое RAII?</p>\n","answer":"<p><strong>Ответ:</strong> Resource Acquisition Is Initialization: владение ресурсом связано с временем жизни объекта, освобождение выполняет деструктор. Работает при normal scope exit и раскрутке исключения.</p>\n<p><strong>Пример:</strong> std::lock_guard освобождает mutex при выходе из scope.</p>\n<p><strong>Источник:</strong> <a href=\"https://isocpp.github.io/CppCoreGuidelines/CppCoreGuidelines#S-resource\">C++ Core Guidelines: Resource management</a></p>\n","group":"🧵 5. C++","line":583},{"id":"content/08_architecture_and_design/01_basic.md:fbbe64adf05196ba:1","question":"<p>(L1 [T]) Что такое указатель?</p>\n","answer":"<p><strong>Ответ:</strong> Значение, представляющее адрес объекта/функции либо null. Сырой указатель не задаёт владение и сам не обеспечивает время жизни адресата.</p>\n<p><strong>Типичная ошибка:</strong> Разыменовывать dangling или null pointer.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/basic.compound\">C++ working draft: Pointers</a>; <a href=\"https://isocpp.github.io/CppCoreGuidelines/CppCoreGuidelines#S-resource\">C++ Core Guidelines: Resource management</a></p>\n","group":"🧵 5. C++","line":591},{"id":"content/08_architecture_and_design/01_basic.md:361ee452b2727e72:1","question":"<p>(L1 [T]) Что такое ссылка?</p>\n","answer":"<p><strong>Ответ:</strong> Ссылка — привязка к объекту/функции, требующая корректного referent; после инициализации её нельзя перепривязать как pointer. Ссылки также могут стать dangling.</p>\n<p><strong>Типичная ошибка:</strong> Считать ссылку гарантией бесконечного времени жизни объекта.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/dcl.ref\">C++ working draft: References</a></p>\n","group":"🧵 5. C++","line":599},{"id":"content/08_architecture_and_design/01_basic.md:cf363f5e390e7d5c:1","question":"<p>(L1 [T]) Что такое стек и куча?</p>\n","answer":"<p><strong>Ответ:</strong> Практические названия областей для вызовов/автоматических объектов и динамических allocations. C++ формально определяет storage duration, а не обязательное физическое размещение каждого объекта на «стеке» или «куче».</p>\n<p><strong>Пример:</strong> Локальный vector обычно имеет автоматическое время жизни, его буфер — динамическое.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/basic.stc\">C++ working draft: Storage duration</a></p>\n","group":"🧵 5. C++","line":607},{"id":"content/08_architecture_and_design/01_basic.md:7d580b4fb28cd13a:1","question":"<p>(L2 [T]) Что такое move semantics?</p>\n","answer":"<p><strong>Ответ:</strong> Передача ресурсов из источника через move-конструктор/присваивание вместо копирования. Перемещённый объект остаётся допустимым в пределах контракта; конкретные члены не обязаны стать пустыми.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/forward\">C++ working draft: forward/move helpers</a>; <a href=\"https://isocpp.github.io/CppCoreGuidelines/CppCoreGuidelines#S-resource\">C++ Core Guidelines: Resource management</a></p>\n","group":"🧵 5. C++","line":616},{"id":"content/08_architecture_and_design/01_basic.md:3af4ec8e84f68373:1","question":"<p>(L2 [P]) Как работает std::unique_ptr?</p>\n","answer":"<p><strong>Ответ:</strong> Владеет объектом единолично, вызывает deleter при уничтожении/reset, не копируется и может перемещаться. Передавать владение нужно явно, release передаёт ответственность вызывающему.</p>\n<p><strong>Пример:</strong> auto p = std::make_unique&lt;int&gt;(42);</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/unique.ptr\">C++ working draft: unique_ptr</a></p>\n","group":"🧵 5. C++","line":622},{"id":"content/08_architecture_and_design/01_basic.md:916f8483748d8253:1","question":"<p>(L2 [T]) Что такое std::shared_ptr?</p>\n","answer":"<p><strong>Ответ:</strong> Совместное владение через control block; объект уничтожается после последнего strong owner. weak_ptr разрывает циклы; потокобезопасность счётчика не делает потокобезопасным сам объект.</p>\n<p><strong>Типичная ошибка:</strong> Создавать два независимых shared_ptr из одного сырого указателя.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/util.smartptr.shared\">C++ working draft: shared_ptr</a></p>\n","group":"🧵 5. C++","line":630},{"id":"content/08_architecture_and_design/01_basic.md:18f84f8f8aa5864f:1","question":"<p>(L2 [P]) Когда использовать std::move?</p>\n","answer":"<p><strong>Ответ:</strong> Когда текущий владелец готов отдать ресурс: std::move делает cast к xvalue и позволяет выбрать move overload. Сам std::move ничего не перемещает; для const объекта может получиться копирование.</p>\n<p><strong>Пример:</strong> auto q = std::move(p); передаёт unique_ptr.</p>\n<p><strong>Рекомендация:</strong> Не писать return std::move(local) без причины: можно мешать NRVO.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/forward\">C++ working draft: forward/move helpers</a></p>\n","group":"🧵 5. C++","line":638},{"id":"content/08_architecture_and_design/01_basic.md:94ebbd089ad48931:1","question":"<p>(L3 [D]) Что такое undefined behavior?</p>\n","answer":"<p><strong>Ответ:</strong> Поведение, для которого стандарт не предъявляет требований. Не обязано приводить к crash; оптимизатор исходит из того, что UB в корректном исполнении отсутствует.</p>\n<p><strong>Пример:</strong> Выход за границы массива, use-after-free и data race.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/defns.undefined\">C++ working draft: Definitions</a></p>\n","group":"🧵 5. C++","line":649},{"id":"content/08_architecture_and_design/01_basic.md:be47fd2746ab5faa:1","question":"<p>(L3 [P]) Как работает custom allocator?</p>\n","answer":"<p><strong>Ответ:</strong> Allocator предоставляет выделение/освобождение storage по контракту контейнера, с нужным alignment и равенством/propagation. Пулы и arena уменьшают overhead, но нужно согласовать lifetime и потокобезопасность.</p>\n<p><strong>Пример:</strong> std::pmr::monotonic_buffer_resource удобен для набора объектов с общим временем жизни.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/allocator.requirements\">C++ working draft: Allocator requirements</a></p>\n","group":"🧵 5. C++","line":657},{"id":"content/08_architecture_and_design/01_basic.md:23674ddb9da7765b:1","question":"<p>(L3 [T]) Что такое memory alignment?</p>\n","answer":"<p><strong>Ответ:</strong> Требование к адресам размещения объектов, обычно кратность заданному выравниванию. Получение достаточного числа байтов без нужного alignment недостаточно; over-aligned типы требуют подходящего allocation.</p>\n<p><strong>Пример:</strong> alignas(64) задаёт повышенное выравнивание объекта.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/basic.align\">C++ working draft: Alignment</a></p>\n","group":"🧵 5. C++","line":665},{"id":"content/08_architecture_and_design/01_basic.md:755a8bbd4d0467c3:1","question":"<p>(L3 [D]) Как найти use-after-free?</p>\n","answer":"<p><strong>Ответ:</strong> Собрать reproducer с AddressSanitizer и debug symbols, получить allocation/free/use stacks. Исправлять модель владения и отмену callbacks, а не только обнулять один из aliases.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/AddressSanitizer.html\">Clang: AddressSanitizer</a>; <a href=\"https://isocpp.github.io/CppCoreGuidelines/CppCoreGuidelines#S-resource\">C++ Core Guidelines: Resource management</a></p>\n","group":"🧵 5. C++","line":673},{"id":"content/08_architecture_and_design/01_basic.md:d14f78a018e3fbe7:1","question":"<p>(L4 [S]) Как проектировать low-latency C++ систему?</p>\n","answer":"<p><strong>Ответ:</strong> Зафиксировать latency budget и распределение нагрузки; минимизировать непредсказуемые allocations, locks, page faults и fan-out на critical path. Проверять p99/p99.9 под пиками, а не только среднее в microbenchmark.</p>\n<p><strong>Источник:</strong> <a href=\"https://research.google/pubs/the-tail-at-scale/\">Dean, Barroso: The Tail at Scale</a>; <a href=\"https://isocpp.github.io/CppCoreGuidelines/CppCoreGuidelines#S-resource\">C++ Core Guidelines: Resource management</a></p>\n","group":"🧵 5. C++","line":680},{"id":"content/08_architecture_and_design/01_basic.md:66330fd7f672ee94:1","question":"<p>(L4 [S]) Как минимизировать аллокации?</p>\n","answer":"<p><strong>Ответ:</strong> Переиспользовать buffers, reserve известную ёмкость, использовать pools/arenas и компактное представление данных. Измерять alloc rate и live memory; чрезмерное резервирование повышает footprint и cache misses.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/allocator.requirements\">C++ working draft: Allocator requirements</a>; <a href=\"https://isocpp.github.io/CppCoreGuidelines/CppCoreGuidelines#S-resource\">C++ Core Guidelines: Resource management</a></p>\n","group":"🧵 5. C++","line":686},{"id":"content/08_architecture_and_design/01_basic.md:51fbd784430028e2:1","question":"<p>(L1 [T]) Что такое mutex?</p>\n","answer":"<p><strong>Ответ:</strong> Примитив взаимного исключения для защиты общего инварианта. Захват/освобождение создают синхронизацию; все обращения к защищённому состоянию должны следовать одному протоколу.</p>\n<p><strong>Пример:</strong> std::lock_guard<a href=\"std::mutex\">std::mutex</a> lock(m);</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/thread.mutex.requirements\">C++ working draft: Mutex requirements</a></p>\n","group":"🔀 6. Concurrency","line":697},{"id":"content/08_architecture_and_design/01_basic.md:a87ab1fa20d42ee6:1","question":"<p>(L1 [T]) Что такое race condition?</p>\n","answer":"<p><strong>Ответ:</strong> Ошибка, при которой результат зависит от взаимного порядка конкурентных событий. Data race — более узкое понятие языка: несинхронизированные конфликтующие обращения к памяти, хотя бы одно — запись.</p>\n<p><strong>Пример:</strong> Проверить наличие файла и затем создать его — race даже без shared-memory data race.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/intro.races\">C++ working draft: Data races</a></p>\n","group":"🔀 6. Concurrency","line":705},{"id":"content/08_architecture_and_design/01_basic.md:a9e3b53f80f7373e:1","question":"<p>(L2 [P]) Как использовать std::thread?</p>\n","answer":"<p><strong>Ответ:</strong> Запустить callable, безопасно передать аргументы и обеспечить join/detach до уничтожения joinable thread. Предпочесть RAII lifecycle; std::jthread с C++20 автоматически join и поддерживает cooperative stop.</p>\n<p><strong>Типичная ошибка:</strong> Уничтожать joinable std::thread: это вызывает std::terminate.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/thread.thread\">C++ working draft: thread</a></p>\n","group":"🔀 6. Concurrency","line":714},{"id":"content/08_architecture_and_design/01_basic.md:3a8471e0e1b34308:1","question":"<p>(L2 [T]) Что такое deadlock?</p>\n","answer":"<p><strong>Ответ:</strong> Цикл ожидания ресурсов, при котором участники не могут продвинуться. Задавать единый порядок locks или применять std::scoped_lock, не выполнять неизвестные callbacks под lock.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/thread.mutex.requirements\">C++ working draft: Mutex requirements</a></p>\n","group":"🔀 6. Concurrency","line":722},{"id":"content/08_architecture_and_design/01_basic.md:b2388c378801d3d6:1","question":"<p>(L2 [T]) Что такое condition variable?</p>\n","answer":"<p><strong>Ответ:</strong> Позволяет ждать изменения предиката, атомарно отпуская mutex на время ожидания. После пробуждения mutex захвачен снова, предикат проверяется из-за spurious wakeups и конкуренции.</p>\n<p><strong>Пример:</strong> <code>cv.wait(lock, [&amp;]{ return ready || stopped; });</code></p>\n<p><strong>Типичная ошибка:</strong> Считать notify сохранённым событием без проверки состояния.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/thread.condition\">C++ working draft: Condition variables</a></p>\n","group":"🔀 6. Concurrency","line":728},{"id":"content/08_architecture_and_design/01_basic.md:8b9bf3e5a1c34b4e:1","question":"<p>(L3 [D]) Как найти data race?</p>\n","answer":"<p><strong>Ответ:</strong> Запустить ThreadSanitizer на конкурентном сценарии, изучить обе stacks и синхронизацию. Ненайденная гонка не доказывает её отсутствия: покрытие и расписание конечны.</p>\n<p><strong>Источник:</strong> <a href=\"https://clang.llvm.org/docs/ThreadSanitizer.html\">Clang: ThreadSanitizer</a>; <a href=\"https://eel.is/c++draft/intro.races\">C++ working draft: Data races</a></p>\n","group":"🔀 6. Concurrency","line":739},{"id":"content/08_architecture_and_design/01_basic.md:0ce5a552a19b29dc:1","question":"<p>(L3 [P]) Что такое lock-free структура?</p>\n","answer":"<p><strong>Ответ:</strong> Структура с гарантией системного прогресса: при конкуренции хотя бы одна операция завершается за конечное число шагов. Это не wait-free и не обязательно быстрее mutex; CAS-цикл требует доказательства и reclamation.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/atomics.order\">C++ working draft: Atomic operations</a>; <a href=\"https://eel.is/c++draft/intro.races\">C++ working draft: Data races</a></p>\n","group":"🔀 6. Concurrency","line":745},{"id":"content/08_architecture_and_design/01_basic.md:6fdeedcc37446cc0:1","question":"<p>(L3 [T]) Что такое memory ordering?</p>\n","answer":"<p><strong>Ответ:</strong> Правила порядка и видимости операций между threads. Release/acquire связывают доступы через соответствующую atomic operation, relaxed сохраняет атомарность без такого порядка для остальных данных.</p>\n<p><strong>Пример:</strong> Запись данных перед release-store становится видна после читающего её acquire-load.</p>\n<p><strong>Рекомендация:</strong> Использовать volatile как замену atomic/synchronization.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/atomics.order\">C++ working draft: Atomic operations</a></p>\n","group":"🔀 6. Concurrency","line":751},{"id":"content/08_architecture_and_design/01_basic.md:cc8a97139535f50a:1","question":"<p>(L4 [S]) Когда использовать actor model?</p>\n","answer":"<p><strong>Ответ:</strong> Для независимых владельцев состояния, обменивающихся сообщениями: сессии, устройства, workflow. Нужны bounded mailboxes, supervision и определённый порядок; actors не устраняют бизнес-гонки между сообщениями.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.erlang.org/doc/system/ref_man_processes.html\">Erlang: Processes</a></p>\n","group":"🔀 6. Concurrency","line":762},{"id":"content/08_architecture_and_design/01_basic.md:dd913cba73bc48dd:1","question":"<p>(L4 [S]) Как проектировать lock-free систему?</p>\n","answer":"<p><strong>Ответ:</strong> Выбирать lock-free только после подтверждения bottleneck, определить linearization points и progress guarantee. Решить ABA и memory reclamation через hazard pointers/epochs либо проверенную библиотеку, проверить sanitizer/stress/model tests.</p>\n<p><strong>Источник:</strong> <a href=\"https://eel.is/c++draft/atomics.order\">C++ working draft: Atomic operations</a>; <a href=\"https://eel.is/c++draft/intro.races\">C++ working draft: Data races</a></p>\n","group":"🔀 6. Concurrency","line":768},{"id":"content/08_architecture_and_design/01_basic.md:c4cdb9fcbdf1bbf4:1","question":"<p>(L1 [T]) Что такое profiling?</p>\n","answer":"<p><strong>Ответ:</strong> Сбор измерений выполнения для определения затрат CPU, памяти, I/O или ожидания. Sampling уменьшает overhead, instrumentation даёт детали, но меняет исследуемое поведение.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man1/perf-record.1.html\">Linux perf: perf record</a>; <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a></p>\n","group":"🔍 7. Debugging & Performance","line":779},{"id":"content/08_architecture_and_design/01_basic.md:0b1ae70fbd737a52:1","question":"<p>(L2 [P]) Как использовать gdb?</p>\n","answer":"<p><strong>Ответ:</strong> Собрать binary с debug symbols, открыть gdb, поставить breakpoint, run, затем bt, info locals и print. Для оптимизированной сборки учитывать inlining/удалённые переменные и проверять соответствие symbols.</p>\n<p><strong>Пример:</strong> gdb ./app; break main; run; bt.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB manual</a></p>\n","group":"🔍 7. Debugging & Performance","line":786},{"id":"content/08_architecture_and_design/01_basic.md:08adaaded96631a0:1","question":"<p>(L2 [P]) Как читать stack trace?</p>\n","answer":"<p><strong>Ответ:</strong> Идти от текущего frame к callers, проверяя аргументы, причины ошибки и thread context. Stacks показывают место наблюдения, а не обязательно первопричину; нужны совпадающие binary/symbols.</p>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB manual</a></p>\n","group":"🔍 7. Debugging & Performance","line":794},{"id":"content/08_architecture_and_design/01_basic.md:a4b481140ffea919:1","question":"<p>(L3 [D]) Как найти bottleneck?</p>\n","answer":"<p><strong>Ответ:</strong> Измерить пользовательский симптом, определить насыщенный ресурс и очередь через USE, затем профиль конкретного участка. Менять одну подтверждённую причину и повторять сопоставимый workload.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.brendangregg.com/usemethod.html\">Brendan Gregg: USE Method</a>; <a href=\"https://man7.org/linux/man-pages/man1/perf-record.1.html\">Linux perf: perf record</a></p>\n","group":"🔍 7. Debugging & Performance","line":801},{"id":"content/08_architecture_and_design/01_basic.md:c08fea3a933ca921:1","question":"<p>(L3 [D]) Как анализировать core dump?</p>\n","answer":"<p><strong>Ответ:</strong> Открыть core с точно соответствующим executable и библиотеками, изучить signal, все thread stacks и значения. Дамп может содержать секреты, а отсутствие core требует проверки limits, core_pattern и coredump handler.</p>\n<p><strong>Пример:</strong> gdb ./app core; thread apply all bt full.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man5/core.5.html\">Linux man-pages: core</a>; <a href=\"https://sourceware.org/gdb/current/onlinedocs/gdb.html/\">GDB manual</a></p>\n","group":"🔍 7. Debugging & Performance","line":807},{"id":"content/08_architecture_and_design/01_basic.md:434f0deb43ceb179:1","question":"<p>(L3 [P]) Как использовать perf?</p>\n","answer":"<p><strong>Ответ:</strong> perf stat показывает аппаратные/системные счётчики, perf record собирает профиль, perf report — stacks и hot paths. Выбор call graph, права и kernel symbols влияют на качество результата.</p>\n<p><strong>Пример:</strong> perf record -g -- ./app, затем perf report.</p>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man1/perf-record.1.html\">Linux perf: perf record</a></p>\n","group":"🔍 7. Debugging & Performance","line":815},{"id":"content/08_architecture_and_design/01_basic.md:be5f9eb93c273906:1","question":"<p>(L4 [S]) Как построить observability систему?</p>\n","answer":"<p><strong>Ответ:</strong> Определить пользовательские SLIs и SLO, внедрить metrics/logs/traces с единым контекстом, collectors, retention и алерты. Контролировать стоимость, кардинальность, доступы и потери telemetry.</p>\n<p><strong>Источник:</strong> <a href=\"https://opentelemetry.io/docs/concepts/signals/\">OpenTelemetry: Signals</a>; <a href=\"https://sre.google/workbook/alerting-on-slos/\">Google SRE Workbook: Alerting on SLOs</a></p>\n","group":"🔍 7. Debugging & Performance","line":824},{"id":"content/08_architecture_and_design/01_basic.md:d313f9d83a7096d0:1","question":"<p>(L4 [S]) Как внедрить distributed tracing?</p>\n","answer":"<p><strong>Ответ:</strong> Инструментировать входы, вызовы и очереди через SDK, передавать trace context, экспортировать spans через collector. Выбрать sampling и доверенные границы, проверить end-to-end trace включая асинхронный путь.</p>\n<p><strong>Источник:</strong> <a href=\"https://opentelemetry.io/docs/concepts/context-propagation/\">OpenTelemetry: Context propagation</a>; <a href=\"https://opentelemetry.io/docs/concepts/sampling/\">OpenTelemetry: Sampling</a></p>\n","group":"🔍 7. Debugging & Performance","line":830},{"id":"content/08_architecture_and_design/01_basic.md:00379cd8f2f3613c:1","question":"<p>(L2 [S]) Спроектировать URL shortener</p>\n","answer":"<p><strong>Ответ:</strong> Начать с create/redirect/expire, QPS и срока хранения. Схема: API генерации → устойчивое mapping(code, URL, owner, expires_at) → redirect service с кэшем; уникальность code защищает БД, аналитику отправлять асинхронно.</p>\n<p><strong>Пример:</strong> POST /links возвращает /aB7x, GET /aB7x отвечает Location.</p>\n<p><strong>Рекомендация:</strong> Уточнить, можно ли менять цель: от этого зависит 301/302 и кэширование.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.rfc-editor.org/rfc/rfc9110.html\">RFC 9110: HTTP Semantics</a>; <a href=\"https://www.postgresql.org/docs/current/indexes.html\">PostgreSQL: Indexes</a>; <a href=\"https://learn.microsoft.com/en-us/azure/architecture/patterns/cache-aside\">Azure Architecture: Cache-Aside</a></p>\n","group":"🧩 8. System Design кейсы","line":841},{"id":"content/08_architecture_and_design/01_basic.md:89ea0f1d639be525:1","question":"<p>(L2 [S]) Спроектировать чат</p>\n","answer":"<p><strong>Ответ:</strong> Определить 1:1/группы, историю, offline и подтверждения. Клиент → WebSocket gateway → message service → durable log/store → доставка online; offline sync читает по cursor, event ID обеспечивает dedup.</p>\n<p><strong>Источник:</strong> <a href=\"https://www.rfc-editor.org/rfc/rfc6455.html\">RFC 6455: WebSocket</a>; <a href=\"https://kafka.apache.org/41/design/design/\">Apache Kafka: Design</a>; <a href=\"https://aws.amazon.com/builders-library/making-retries-safe-with-idempotent-APIs/\">AWS: Making retries safe with idempotent APIs</a></p>\n","group":"🧩 8. System Design кейсы","line":851},{"id":"content/08_architecture_and_design/01_basic.md:f40d33cec82b9987:1","question":"<p>(L3 [S]) Спроектировать rate limiter</p>\n","answer":"<p><strong>Ответ:</strong> Выбрать identity, единицу стоимости и модель bucket/window; атомарно обновлять состояние и возвращать понятный отказ. Для глобального лимита определить квоты регионов, допускаемый overshoot и поведение при недоступности счётчика.</p>\n<p><strong>Источник:</strong> <a href=\"https://docs.nginx.com/nginx/admin-guide/security-controls/controlling-access-proxied-http/\">NGINX: Limiting access</a>; <a href=\"https://raft.github.io/raft.pdf\">Raft paper</a></p>\n","group":"🧩 8. System Design кейсы","line":858},{"id":"content/08_architecture_and_design/01_basic.md:9857870dc481e8d9:1","question":"<p>(L3 [S]) Спроектировать лог-систему</p>\n","answer":"<p><strong>Ответ:</strong> Агенты собирают структурированные события в bounded durable buffer, затем broker/collector доставляет их в partitioned storage/index. Определить retention, redaction, tenant quotas и at-least-once replay с dedup.</p>\n<p><strong>Источник:</strong> <a href=\"https://opentelemetry.io/docs/collector/resiliency/\">OpenTelemetry Collector: Resiliency</a>; <a href=\"https://kafka.apache.org/41/design/design/\">Apache Kafka: Design</a></p>\n","group":"🧩 8. System Design кейсы","line":864},{"id":"content/08_architecture_and_design/01_basic.md:6a67df03f84a4c74:1","question":"<p>(L4 [S]) Спроектировать HFT систему</p>\n","answer":"<p><strong>Ответ:</strong> Определить рыночные feeds, order gateway, risk checks и пределы задержки; критический путь делать предсказуемым с bounded queues, preallocation и контролируемым single-writer state. Нужны детерминированный журнал/replay, отказобезопасное управление ордерами и измерение хвостов.</p>\n<p><strong>Типичная ошибка:</strong> Оптимизировать nanoseconds, не определив порядок событий, риск-лимиты и восстановление после disconnect.</p>\n<p><strong>Источник:</strong> <a href=\"https://lmax-exchange.github.io/disruptor/disruptor.html\">LMAX: Architecture</a>; <a href=\"https://research.google/pubs/the-tail-at-scale/\">Dean, Barroso: The Tail at Scale</a></p>\n","group":"🧩 8. System Design кейсы","line":871},{"id":"content/08_architecture_and_design/01_basic.md:7e9e9f13d9a13ddb:1","question":"<p>(L4 [S]) Спроектировать distributed filesystem</p>\n","answer":"<p><strong>Ответ:</strong> Разделить metadata/namespace и data chunks, хранить реплики в разных failure domains. Определить consistency записи/append, lease/fencing, checksum, repair/rebalance и поведение клиента при отказе; metadata требует надёжной координации.</p>\n<p><strong>Источник:</strong> <a href=\"https://research.google.com/archive/gfs.html\">Google File System paper</a>; <a href=\"https://raft.github.io/raft.pdf\">Raft paper</a></p>\n","group":"🧩 8. System Design кейсы","line":879}];
